mapper.sql:
select u.`id`, u.`username`, u.`age`, u.`role_id`, r.`name` as role_name, u.`sex`, u.`sex` as `sex_name`, u.`email`, u.`qq`, u.`wechat`, u.`address`, u.`avatar`, u.`phone`, u.`status`, u.`create_time`, u.`update_time` from smart_villages_permission.user u left join smart_villages_permission.role r on u.`role_id` = r.`id`
u.`id`=#{user.id}
AND u.`username` LIKE concat('%',#{user.username},'%')
AND u.`age`=#{user.age}
AND u.`role_id`=#{user.roleId}
AND u.`sex`=#{user.sex}
AND u.`email`=#{user.email}
AND u.`qq`=#{user.qq}
AND u.`wechat`=#{user.wechat}
AND u.`address` like concat('%',#{user.address},'%')
AND u.`phone`=#{user.phone}
AND u.`status`=#{user.status}
and `u`.deleted=0 and `r`.deleted=0
order by `u`.create_time desc

